package com.vircas.mobile.ui

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

private val caseArtworkBase64 = mapOf(
    "aurora" to "",
    "eclipse" to "",
    "ember" to "",
    "frost" to "",
    "neon" to "",
    "orbit" to "",
    "prism" to "",
    "reactor" to "",
    "void" to ""
)

@Composable
internal fun CaseItemArtwork(previewKey: String, modifier: Modifier = Modifier) {
    val bitmap = remember(previewKey) {
        val encoded = caseArtworkBase64[previewKey] ?: caseArtworkBase64.getValue("ember")
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }
    Box(modifier, contentAlignment = Alignment.Center) {
        bitmap?.let {
            Image(
                bitmap = it,
                contentDescription = null,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.Fit
            )
        }
    }
}
